ey name=\"woocommerce_cancelled_order_settings\">\r\n			<key name=\"subject\" />\r\n			<key name=\"heading\" />\r\n		</key>\r\n		<key name=\"woocommerce_failed_order_settings\">\r\n			<key name=\"subject\" />\r\n			<key name=\"heading\" />\r\n		</key>\r\n		<key name=\"woocommerce_customer_on_hold_order_settings\">\r\n			<key name=\"subject\" />\r\n			<key name=\"heading\" />\r\n		</key>\r\n		<key name=\"woocommerce_customer_refunded_order_settings\">\r\n			<key name=\"subject_full\" />\r\n			<key name=\"heading_full\" />\r\n			<key name=\"subject_partial\" />\r\n			<key name=\"heading_partial\" />\r\n		</key>\r\n		<key name=\"woocommerce_demo_store_notice\"/>\r\n		<key name=\"woocommerce_price_thousand_sep\"/>\r\n		<key name=\"woocommerce_price_decimal_sep\"/>\r\n		<key name=\"woocommerce_price_display_suffix\" />\r\n		<key name=\"woocommerce_email_from_name\"/>\r\n		<key name=\"woocommerce_email_from_address\" />\r\n		<key name=\"woocommerce_registration_privacy_policy_text\" />\r\n		<key name=\"woocommerce_checkout_privacy_policy_text\" />\r\n		<key name=\"woocommerce_checkout_terms_and_conditions_checkbox_text\" />\r\n	</admin-texts>\r\n	<gutenberg-blocks>\r\n		<gutenberg-block type=\"woocommerce/checkout-contact-information-block\" translate=\"1\">\r\n			<key name=\"title\" />\r\n			<key name=\"description\" />\r\n		</gutenberg-block>\r\n		<gutenberg-block type=\"woocommerce/checkout-shipping-address-block\" translate=\"1\">\r\n			<key name=\"title\" />\r\n			<key name=\"description\" />\r\n		</gutenberg-block>\r\n		<gutenberg-block type=\"woocommerce/checkout-shipping-methods-block\" translate=\"1\">\r\n			<key name=\"title\" />\r\n			<key name=\"description\" />\r\n		</gutenberg-block>\r\n		<gutenberg-block type=\"woocommerce/checkout-payment-block\" translate=\"1\">\r\n			<key name=\"title\" />\r\n			<key name=\"description\" />\r\n		</gutenberg-block>\r\n		<gutenberg-block type=\"woocommerce/checkout-terms-block\" translate=\"1\">\r\n			<key name=\"text\" />\r\n		</gutenberg-block>\r\n		<gutenberg-block type=\"woocommerce/cart-order-summary-heading-block\" translate=\"1\">\r\n			<key name=\"content\" />\r\n		</gutenberg-block>\r\n		<gutenberg-block type=\"woocommerce/proceed-to-checkout-block\" translate=\"1\">\r\n			<key name=\"buttonLabel\" />\r\n		</gutenberg-block>\r\n		<gutenberg-block type=\"woocommerce/product-search\" translate=\"1\">\r\n			<xpath>//*[contains(@class, \"wc-block-product-search__label\")]</xpath>\r\n			<xpath>//*[contains(@class, \"wc-block-product-search__field\")]/@placeholder</xpath>\r\n			<xpath>//*[contains(@class, \"wc-block-product-search__button\")]/@label</xpath>\r\n		</gutenberg-block>\r\n		<gutenberg-block type=\"woocommerce/featured-category\" translate=\"1\">\r\n			<xpath>//*[contains(@class, \"wp-block-button__link\")]</xpath>\r\n		</gutenberg-block>\r\n		<gutenberg-block type=\"woocommerce/featured-product\" translate=\"1\">\r\n			<xpath>//*[contains(@class, \"wp-block-button__link\")]</xpath>\r\n		</gutenberg-block>\r\n		<gutenberg-block type=\"woocommerce/active-filters\" translate=\"1\">\r\n			<xpath>//*[contains(@class, \"wp-block-woocommerce-active-filters\")]/@data-heading</xpath>\r\n		</gutenberg-block>\r\n		<gutenberg-block type=\"woocommerce/attribute-filter\" translate=\"1\">\r\n			<xpath>//*[contains(@class, \"wp-block-woocommerce-attribute-filter\")]/@data-heading</xpath>\r\n		</gutenberg-block>\r\n		<gutenberg-block type=\"woocommerce/price-filter\" translate=\"1\">\r\n			<xpath>//*[contains(@class, \"wp-block-woocommerce-price-filter\")]/@data-heading</xpath>\r\n		</gutenberg-block>\r\n		<gutenberg-block type=\"woocommerce/all-products\" translate=\"0\"></gutenberg-block>\r\n		<gutenberg-block type=\"woocommerce/all-reviews\" translate=\"0\"></gutenberg-block>\r\n		<gutenberg-block type=\"woocommerce/reviews-by-product\" translate=\"0\"></gutenberg-block>\r\n		<gutenberg-block type=\"woocommerce/reviews-by-category\" translate=\"0\"></gutenberg-block>\r\n	</gutenberg-blocks>\r\n</wpml-config>\r\n\r\n\";s:25:\"WPML Multilingual for CF7\";s:766:\"<wpml-config>\n	<custom-types>\n		<custom-type translate=\"1\">wpcf7_contact_form</custom-type>\n	</custom-types>\n	<custom-fields>\n		<custom-field action=\"translate\">_form</custom-field>\n		<custom-field action=\"translate\">_mail</custom-field>\n		<custom-field action=\"translate\">_mail_2</custom-field>\n		<custom-field action=\"translate\">_messages</custom-field>\n		<custom-field action=\"copy\">_additional_settings</custom-field>\n		<custom-field action=\"copy\">_locale</custom-field>\n		<custom-field action=\"copy\">_hash</custom-field>\n	</custom-fields>\n	<custom-fields-texts>\n		<key name=\"_mail\">\n			<key name=\"subject\" />\n			<key name=\"body\" />\n		</key>\n		<key name=\"_mail_2\">\n			<key name=\"subject\" />\n			<key name=\"body\" />\n		</key>\n	</custom-fields-texts>\n</wpml-config>\n\";}}', 'off');
INSERT INTO `wp_options` (`option_id`, `option_name`, `option_value`, `autoload`) VALUES
(1078, 'wpml_global_notices_config', '<wpml-config>\n    <notices>\n        <notice type=\"info\" dismissible=\"1\" id=\"compdev-560-learndash\">\n            <!-- https://onthegosystems.myjetbrains.com/youtrack/issue/compdev-560/ -->\n            <conditions>\n                <plugin>LearnDash LMS</plugin>\n            </conditions>\n            <locations>\n                <screenId>toplevel_page_tm/menu/main</screenId>\n            </locations>\n            <content><![CDATA[\n<p style=\"margin-top:6px;\">\nRemember to manually connect your LearnDash components after translating them. <a target=\"_blank\" href=\"https://wpml.org/documentation/plugins-compatibility/how-to-create-multilingual-online-courses-websites-using-learndash-and-wpml/?utm_source=plugin&utm_medium=gui&utm_campaign=core\">Learn how to do this</a>.\n</p>\n]]></content>\n        </notice>\n        <notice id=\"compdev-762-wp-residence\" dismissible=\"1\">\n            <!-- https://onthegosystems.myjetbrains.com/youtrack/issue/compdev-762/ -->\n            <conditions>\n                <theme>WpResidence</theme>\n            </conditions>\n            <locations>\n                <screenId>toplevel_page_tm/menu/main</screenId>\n            </locations>\n            <content><![CDATA[\n<p style=\"margin-top:6px;\">\nTo translate custom fields created with WP Residence, set their translation preferences in <a target=\"_blank\" href=\"/wp-admin/admin.php?page=tm%2Fmenu%2Fsettings&sm=mcsetup#ml-content-setup-sec-cf\">WPML → Settings</a>.\n</p>\n        ]]></content>\n        </notice>\n        <notice id=\"compdev-765-jetengine\" dismissible=\"1\">\n            <!-- https://onthegosystems.myjetbrains.com/youtrack/issue/compdev-765/ -->\n            <conditions>\n                <plugin>JetEngine</plugin>\n            </conditions>\n            <locations>\n                <screenId>toplevel_page_tm/menu/main</screenId>\n            </locations>\n            <content>\n                <![CDATA[\n<p style=\"margin-top:6px;\">\nTo translate custom post types, custom fields, and taxonomies created with JetEngine, you first need to make them translatable. <a target=\"_blank\" href=\"https://wpml.org/documentation/plugins-compatibility/how-to-translate-jetengine-with-wpml/?utm_source=plugin&utm_medium=gui&utm_campaign=core\">Learn how to do this</a>.\n</p>\n        ]]>\n            </content>\n        </notice>\n        <notice id=\"compdev-764-events-manager\" dismissible=\"1\" type=\"warning\">\n            <!-- https://onthegosystems.myjetbrains.com/youtrack/issue/compdev-764/ -->\n            <conditions>\n                <plugin>Events Manager</plugin>\n            </conditions>\n            <locations>\n                <screenId>toplevel_page_tm/menu/main</screenId>\n                <screenId>edit-event</screenId>\n            </locations>\n            <content>\n                <![CDATA[\n<p style=\"margin-top:6px;\">\nEvents Manager is no longer compatible with WPML, so you won’t be able to translate your events. <a target=\"_blank\" href=\"https://wpml.org/plugin-functionality/calendar/?utm_source=plugin&utm_medium=gui&utm_campaign=core\">Here’s a list of other recommended plugins</a>.\n</p>\n        ]]>\n            </content>\n        </notice>\n        <notice id=\"compdev-760-formidable\" dismissible=\"1\">\n            <!-- https://onthegosystems.myjetbrains.com/youtrack/issue/compdev-760/ -->\n            <conditions>\n                <plugin>Formidable Forms</plugin>\n            </conditions>\n            <locations>\n                <screenId>toplevel_page_tm/menu/main</screenId>\n            </locations>\n            <content>\n                <![CDATA[\n<p style=\"margin-top:6px;\">\nTo translate Formidable Forms with WPML, install the WP Multilingual add-on from Formidable Forms. Then, use the Formidable editor to manually translate your forms. <a target=\"_blank\" href=\"https://wpml.org/documentation/plugins-compatibility/how-to-translate-formidable-forms-with-wpml/?utm_source=plugin&utm_medium=gui&utm_campaign=core\">Learn more</a>\n</p>\n        ]]>\n            </content>\n        </notice>\n        <notice id=\"compdev-778-oxygen-builder\" dismissible=\"1\" type=\"warning\">\n            <!-- https://onthegosystems.myjetbrains.com/youtrack/issue/compdev-778 -->\n            <conditions>\n                <plugin>Oxygen</plugin>\n            </conditions>\n            <locations>\n                <screenId>toplevel_page_tm/menu/main</screenId>\n            </locations>\n            <content>\n                <![CDATA[\n<p style=\"margin-top:6px;\">\nOxygen Builder is not compatible with WPML. Here’s a <a target=\"_blank\" href=\"https://wpml.org/plugin-functionality/page-builder/?utm_source=plugin&utm_medium=gui&utm_campaign=core\">list of recommended page builders for multilingual sites</a>.\n</p>\n        ]]>\n            </content>\n        </notice>\n        <notice id=\"compdev-777-breakdance\" dismissible=\"1\" type=\"warning\">\n            <!-- https://onthegosystems.myjetbrains.com/youtrack/issue/compdev-777 -->\n            <conditions>\n                <plugin>Breakdance</plugin>\n            </conditions>\n            <locations>\n                <screenId>toplevel_page_tm/menu/main</screenId>\n            </locations>\n            <content>\n                <![CDATA[\n<p style=\"margin-top:6px;\">\nBreakdance is not compatible with WPML. Here’s a <a target=\"_blank\" href=\"https://wpml.org/plugin-functionality/page-builder/?utm_source=plugin&utm_medium=gui&utm_campaign=core\">list of recommended page builders for multilingual sites</a>.\n</p>\n        ]]>\n            </content>\n        </notice>\n    </notices>\n</wpml-config>\n', 'off'),
